import {chromium} from 'playwright';

const url = process.argv[2];
const outDir = process.argv[3];
const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1280, height: 640}});

const chunks = [];
const errors = [];
page.on('request', (r) => {
    const m = r.url().match(/assets\/(\w+Widget)-/);
    if (m) chunks.push(m[1]);
});
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('pageerror', (e) => errors.push(String(e)));

await page.goto(url, {waitUntil: 'networkidle'});
await page.waitForSelector('.viz-widget__plot svg path', {timeout: 15000});
console.log('after initial load (sales):', JSON.stringify(chunks));
await page.screenshot({path: `${outDir}/sales.png`});

await page.mouse.move(640, 300);
await page.waitForTimeout(300);
await page.screenshot({path: `${outDir}/sales-hover.png`});

await page.getByText('Мониторинг', {exact: true}).click();
await page.waitForSelector('.viz-widget__plot canvas', {timeout: 15000});
await page.waitForTimeout(500);
console.log('after switch to monitoring:', JSON.stringify(chunks));
await page.screenshot({path: `${outDir}/monitoring.png`});

await page.mouse.move(800, 300);
await page.waitForTimeout(300);
await page.screenshot({path: `${outDir}/monitoring-hover.png`});

await page.getByText('Продажи', {exact: true}).click();
await page.waitForSelector('.viz-widget__plot svg path', {timeout: 15000});
console.log('after switch back to sales:', JSON.stringify(chunks));

console.log('errors:', JSON.stringify(errors));
await browser.close();

